/// imm5=8 (power of 2 (2^3 = 8))
#[test]
fn test_ldff1sh_z_p_ai_d_combo_5_a000_c4a8a000() {
    // Encoding: 0xC4A8A000
    // Test LDFF1SH_Z.P.AI_D field combination: imm5=8, Pg=0, Zn=0, Zt=0
    // Fields: imm5=8, Zn=0, Zt=0, Pg=0
    let encoding: u32 = 0xC4A8A000;
    let mut cpu = create_test_cpu();
    write_insn(&mut cpu, 0, encoding);
    let exit = cpu.step().unwrap();
    assert_eq!(
        exit,
        CpuExit::Continue,
        "instruction 0x{:08X} should execute successfully",
        encoding
    );
}

