/// Zm=1 (SIMD register V1)
#[test]
fn test_fmul_z_zzi_h_combo_6_2000_64212000() {
    // Encoding: 0x64212000
    // Test FMUL_Z.ZZi_H field combination: i3h=0, i3l=0, Zm=1, Zn=0, Zd=0
    // Fields: Zm=1, i3h=0, i3l=0, Zn=0, Zd=0
    let encoding: u32 = 0x64212000;
    let mut cpu = create_test_cpu();
    write_insn(&mut cpu, 0, encoding);
    let exit = cpu.step().unwrap();
    assert_eq!(
        exit,
        CpuExit::Continue,
        "instruction 0x{:08X} should execute successfully",
        encoding
    );
}

